import {
  Workspace,
  WorkspaceContent,
} from "@/components/blocks/openlmis/workspace"
import { NoAccess } from "@/components/openlmis/no-access"

/** A whole page the signed-in user's roles do not reach, in place of the page. Render it inside your app shell. */
export function NoAccessPage({ homeHref = "/" }: { homeHref?: string }) {
  return (
    <Workspace>
      <WorkspaceContent>
        <NoAccess heading="h1" homeHref={homeHref} />
      </WorkspaceContent>
    </Workspace>
  )
}

import { NoAccessPage } from "@/components/openlmis/no-access-page/no-access-page"

// A Next.js App Router route; in any other React app, render NoAccessPage from your own route.
export default function Page() {
  return <NoAccessPage />
}
